pub fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Create a reverse iterator over Unicode scalar values (chars)
    let mut rev_chars = txt.chars().rev();

    // Step 1: Get the last character (if any)
    match rev_chars.next() {
        None => return false, // empty string
        Some(last) => {
            // Step 2: Check if the last character is an ASCII letter
            if !last.is_ascii_alphabetic() {
                return false;
            }
        }
    }

    // Step 3: Check the character immediately before the last (if any)
    match rev_chars.next() {
        None => true,            // only one character in the string, and it's an ASCII letter
        Some(prev) => prev == ' ' // must be a space
    }
}